// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint v, uint _decimals) public {
        // Ensure a non-empty array to satisfy the require in transfer
        vm.assume(_tos.length > 0);
        // Prevent overflow in value computation
        vm.assume(v <= type(uint256).max / 10 ** _decimals);
        // Ensure _decimals is not too large to avoid overflow in 10**_decimals
        vm.assume(_decimals <= 77);

        // Deploy a helper contract that will succeed on any low-level call,
        // so the transfer function completes without reverting.
        Succeeder helper = new Succeeder();

        // Call the transfer function
        bool returned;
        try c.transfer(from, address(helper), _tos, v, _decimals) returns (bool result) {
            returned = result;
        } catch {
            returned = false;
        }

        // The invariant: if the call completed without reverting, it must return true.
        // The buggy version returns false on successful completion, violating this.
        assertTrue(returned == true);
    }
}

contract Succeeder {
    fallback() external payable { }
}
